def a(h,m,b):
    text = 'All'
    if h < 1:
        return 0

    elif h< 5:
        text = text + ' a'
    else:
        text = text + ' as'

    while h > 0:
        text = text + ' little'
        h -= 1
    if m > 0:
        text = text + ' man'
    elif m < 0:
        text = text + ' boy'
    else:
        text = text + ' ma'
    if b < 0:
        text = text + ' stone'
    return text

