from functools import wraps

def memoize(f):
    cache = {}
    @wraps(f)
    def memf(*args, **kwargs):
        if args in cache:
            return cache[args]
        result = f(*args, **kwargs)
        cache[args] = result
        return result
    return memf

@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

print(fib(50))

